<script setup>
import UsageProgress from './UsageProgress.vue';
defineProps({ summary: Object });
const label = key => key.replaceAll('_',' ').replace(/\b\w/g, c => c.toUpperCase());
const remaining = date => Math.max(0, Math.ceil((new Date(date) - new Date()) / 86400000));
</script>
<template><div class="cs-subscription"><div class="cs-plan"><div><small>CURRENT PLAN</small><h2>{{ summary.plan?.name || 'No plan' }}</h2><p class="capitalize">{{ summary.subscription?.status }}</p></div><p v-if="summary.subscription?.trial_ends_at">Trial ends {{ new Date(summary.subscription.trial_ends_at).toLocaleDateString() }}<br>{{ remaining(summary.subscription.trial_ends_at) }} days remaining</p></div><div class="cs-fields"><UsageProgress v-for="[label, key, limit] in [['Branches','branches','branch_limit'],['Members','tenant_memberships','member_limit'],['Doctors','doctors','doctor_limit'],['Patients','patients','patient_limit']]" :key="key" :label="label" :used="summary.usage[key]" :limit="summary.limits[limit]" /><UsageProgress label="Storage (MB)" :used="Math.round(summary.usage.storage_bytes / 1048576 * 100) / 100" :limit="summary.limits.storage_limit_gb == null ? null : summary.limits.storage_limit_gb * 1024" /></div><h3 class="mt-6 font-semibold">Enabled Features</h3><div class="cs-features"><span v-for="key in Object.keys(summary.features).filter(k => summary.features[k])" :key="key">{{ label(key) }}</span></div><p class="cs-hint mt-5">Plan changes are managed by the platform administrator. Contact them to review plans or upgrade your subscription.</p><a v-if="summary.support_email" class="btn inline-block mt-4" :href="`mailto:${summary.support_email}?subject=Clinic%20subscription%20upgrade`">Contact Platform Administrator</a></div></template>
